Etheta = zeros(21,91);Ephi = zeros(21,91);weight_mat = zeros(1,91);weight_max = 1;weight_min = 1;for i = 1:91    weight_mat(1,i) = weight_max - (weight_max-weight_min)*sqrt(abs(i-46)/10);endZ_0 = 50; % Characteristic ImpedanceZ_targ = 50; % Target Input Impedancef = 1e10; % Operating Frequencyw = 2*pi*f;e_0 = 8.8541878188e-12; % Permittivity of Free Spaceu_0 = 4*pi*1e-7; % Permeability of Free Spacek = w*sqrt(u_0*e_0); % WavenumberC_min = 0.14e-12; % Minimum Capacitance (F)C_max = 1.1e-12; % Maximum Capacitance (F)d = 0.00625; % Cell Length (m)for i = 1:21    [theta,phi,numFreqs,Etheta_temp,Ephi_temp,freqs] = loadData("element_patterns/straight_ms_10mm_3-5mm/straight_3-5mm_"+i+".ffd","Phi-Theta");    Etheta(i,:) = Etheta_temp;    Ephi(i,:) = Ephi_temp;endE_rl = zeros(1,91);E_targ = zeros(1,91);for n = 1:21    E_targ = E_targ + exp(1i*(n-1)*k*d.*sind(theta))/21;    E_rl = E_rl + Etheta(n,:);endE_rl_max = max(E_rl,[],"all");E_rl = E_rl ./ E_rl_max;% E_targ = 1/21.*(sin(21/2*k*d.*cos(theta))./sin(1/2*k*d.*cos(theta)));[x0,Z_LL,Z_LE,Z_EL,Z_EE] = loadMat("straight_microstrip_zmatrix/UnitCell_Meander_Array_1D_Array_Straight_ZMat_3-5mm_ms.s21p",Z_0,Z_targ,f,C_min,C_max,21,11,-80);I_E = 1;fun = @(x) radError(x,E_targ,Etheta,Z_LL,Z_LE,I_E,weight_mat);options = optimoptions(@fmincon, 'Display','iter', MaxFunctionEvaluations=1000000, UseParallel=true);% X_mat = fmincon(fun,x0,[],[],[],[],-1/(w*C_min)*ones(1,20),-1/(w*C_max)*ones(1,20),[],options);X_mat = fmincon(fun,x0,[],[],[],[],10,100,[],options);% C_mat = -1 ./ (w .* X_mat);L_mat = X_mat ./ w;